#!/usr/bin/env bash
# Boot the local authentik dev stack and wait until its API answers.
# Generates docker/.env with fresh random secrets on first run, then reuses it.
set -euo pipefail

cd "$(dirname "$0")"

if [[ ! -f .env ]]; then
  echo "==> generating docker/.env with random secrets"
  cat > .env <<EOF
# Generated by up.sh on $(date -Iseconds). Local dev only - do not commit.
AUTHENTIK_TAG=2026.8.3
AUTHENTIK_PORT_HTTP=9000
AUTHENTIK_PORT_HTTPS=9443

PG_USER=authentik
PG_DB=authentik
PG_PASS=$(openssl rand -hex 24)

AUTHENTIK_SECRET_KEY=$(openssl rand -base64 48 | tr -d '\n')
AUTHENTIK_BOOTSTRAP_PASSWORD=$(openssl rand -hex 16)
AUTHENTIK_BOOTSTRAP_TOKEN=$(openssl rand -hex 32)
AUTHENTIK_BOOTSTRAP_EMAIL=admin@localhost
EOF
  chmod 600 .env
fi

# shellcheck disable=SC1091
set -a; source .env; set +a

docker compose up -d

url="http://localhost:${AUTHENTIK_PORT_HTTP:-9000}"
echo "==> waiting for authentik at ${url} (first boot runs migrations, ~1-2 min)"
for i in $(seq 1 120); do
  if curl -fsS -o /dev/null "${url}/-/health/ready/" 2>/dev/null; then
    echo "==> authentik is ready after ${i}0s"
    break
  fi
  if [[ $i -eq 120 ]]; then
    echo "!! timed out; check: docker compose -f docker/compose.yml logs server" >&2
    exit 1
  fi
  sleep 10
done

cat <<EOF

authentik UI : ${url}/if/admin/
  user       : akadmin
  password   : ${AUTHENTIK_BOOTSTRAP_PASSWORD}

Terraform:
  export TF_VAR_authentik_url="${url}"
  export TF_VAR_authentik_token="${AUTHENTIK_BOOTSTRAP_TOKEN}"
EOF
